export const add=(a,b)=>a.map((v,i)=>v+b[i]);
export const sub=(a,b)=>a.map((v,i)=>v-b[i]);
export const mul=(a,n)=>a.map(v=>v*n);
export const dot=(a,b)=>a.reduce((s,v,i)=>s+v*b[i],0);
export const length=a=>Math.hypot(...a);
export const norm=a=>mul(a,1/(length(a)||1));
export const dist=(a,b)=>length(sub(a,b));
export const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export function rng(seed){return ()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return ((t^t>>>14)>>>0)/4294967296;};}
export function segmentSphere(a,b,c,r){const d=sub(b,a),o=sub(a,c),A=dot(d,d),C=dot(o,o)-r*r;if(C<=0)return 0;if(A<1e-12)return null;const B=dot(o,d),D=B*B-A*C;if(D<0)return null;const t=(-B-Math.sqrt(D))/A;return t>=0&&t<=1?t:null;}
export function makeUniverse(){const rand=rng(1988),types=['ROCKY','GAS GIANT','ICE WORLD','OCEAN WORLD','VOLCANIC'];const planets=[{id:0,name:'Earth',pos:[-350,95,-1050],radius:230,type:'HOMEWORLD',hue:.58,hostile:false,seed:1},{id:1,name:'Asterion',pos:[4350,180,-10250],radius:190,type:'ROCKY',hue:.075,hostile:true,seed:22},{id:2,name:'Kepler Reach',pos:[-11000,-450,-16000],radius:470,type:'GAS GIANT',hue:.11,hostile:false,seed:35},{id:3,name:'Pelagos',pos:[12000,900,-26000],radius:310,type:'OCEAN WORLD',hue:.54,hostile:true,seed:59},{id:4,name:'Nivalis',pos:[-8700,2000,-35100],radius:220,type:'ICE WORLD',hue:.58,hostile:false,seed:78},{id:5,name:'Ember',pos:[23600,-900,-39800],radius:300,type:'VOLCANIC',hue:.025,hostile:true,seed:98}];for(let i=6;i<1200;i++){let pos;do{pos=[(rand()-.5)*240000,(rand()-.5)*120000,(rand()-.5)*240000];}while(length(pos)<17000);const type=types[Math.floor(rand()*types.length)];planets.push({id:i,name:`${['Tau','Epsilon','Vega','Orion','Atlas','Nova','Lyra','Echo'][i%8]} ${String(i).padStart(4,'0')}`,pos,radius:90+rand()*560,type,hue:rand(),hostile:rand()<.3,seed:i*431});}return planets;}
export class Game{
 constructor(name='Replicant'){this.name=name;this.planets=makeUniverse();this.ships=[];this.enemies=[];this.missiles=[];this.events=[];this.time=0;this.kills=0;this.visited=new Set([0]);this.spawned=new Set();this.nextId=1;this.leader=this.makeShip([0,0,0],name);this.yaw=0;this.pitch=0;this.warp=false;this.autopilot=false;this.targetPlanet=1;this.paused=true;this.over=false;this.cooldowns={missile:0,rail:0};this.cloneProgress=0;this.cloneLatch=false;this.localPlanets=this.planets.slice(0,6);this.refresh=0;this.hitTime=-100;this.shots={rail:0,missile:0};}
 makeShip(pos,name){const s={id:this.nextId++,name,pos:[...pos],vel:[0,0,0],hp:100,fire:0,dir:[0,0,-1]};this.ships.push(s);return s;}
 forward(){return [Math.sin(this.yaw)*Math.cos(this.pitch),Math.sin(this.pitch),-Math.cos(this.yaw)*Math.cos(this.pitch)];}
 aimTarget(pos=this.leader.pos,dir=this.forward(),range=2000){let best=null,score=.975;for(const e of this.enemies){if(e.hp<=0)continue;const delta=sub(e.pos,pos),d=length(delta),s=dot(norm(delta),dir);if(d<range&&s>score){score=s;best=e;}}return best;}
 event(type,data={}){this.events.push({type,...data});}
 repel(pos,previous,r=9){for(const p of this.localPlanets){const rad=p.radius+r+5;let delta=sub(pos,p.pos);const t=segmentSphere(previous,pos,p.pos,rad);if(t!==null){const contact=add(previous,mul(sub(pos,previous),t));const normal=norm(sub(contact,p.pos));let remaining=mul(sub(pos,previous),1-t);remaining=sub(remaining,mul(normal,Math.min(0,dot(remaining,normal))));pos=add(add(p.pos,mul(normal,rad+.2)),remaining);delta=sub(pos,p.pos);}if(length(delta)<rad)pos=add(p.pos,mul(length(delta)>.001?norm(delta):[0,1,0],rad+.2));}return pos;}
 replicate(){if(this.ships.length>=50)return false;const right=[Math.cos(this.yaw),0,Math.sin(this.yaw)];let pos=add(this.leader.pos,mul(right,30+this.ships.length*2));pos=this.repel(pos,this.leader.pos);const ship=this.makeShip(pos,`${this.name} · ${String(this.nextId-1).padStart(2,'0')}`);ship.dir=this.forward();this.event('clone',{id:ship.id});return true;}
 switchShip(){if(this.ships.length<2)return;const i=this.ships.indexOf(this.leader);this.leader=this.ships[(i+1)%this.ships.length];const d=this.leader.dir;this.yaw=Math.atan2(d[0],-d[2]);this.pitch=Math.asin(clamp(d[1],-1,1));this.autopilot=false;this.event('switch');}
 cycleDestination(){const nearest=this.planets.filter(p=>dist(p.pos,this.leader.pos)>p.radius+150).sort((a,b)=>dist(a.pos,this.leader.pos)-dist(b.pos,this.leader.pos)).slice(0,12);let i=nearest.findIndex(p=>p.id===this.targetPlanet);this.targetPlanet=nearest[(i+1)%nearest.length].id;this.autopilot=false;}
 fire(kind,ship=this.leader,target=null){if(this.paused||this.over||ship.hp<=0)return false;const main=ship===this.leader;if(main&&this.cooldowns[kind]>0)return false;let dir=main?this.forward():norm(sub(target.pos,ship.pos));target=target||this.aimTarget(ship.pos,dir);const origin=add(ship.pos,mul(dir,16));if(kind==='missile'){this.missiles.push({id:this.nextId++,pos:origin,dir,life:8,target:target?.id??null,team:'ally',speed:240});this.event('missile',{pos:origin});if(main)this.shots.missile++;}else{let end=add(origin,mul(dir,2200)),hit=null,best=1;for(const e of this.enemies){const t=segmentSphere(origin,end,e.pos,16);if(e.hp>0&&t!==null&&t<best){best=t;hit=e;}}for(const p of this.localPlanets){const t=segmentSphere(origin,end,p.pos,p.radius);if(t!==null&&t<best){best=t;hit=null;}}end=add(origin,mul(sub(end,origin),best));if(hit)this.damage(hit,42,'enemy');this.event('beam',{from:origin,to:end,team:'ally',hit:!!hit});if(main)this.shots.rail++;}if(main)this.cooldowns[kind]=kind==='missile'?1.4:.32;return true;}
 damage(ship,amount,team){if(ship.hp<=0)return;ship.hp=Math.max(0,ship.hp-amount);this.event('hit',{pos:[...ship.pos],team});if(team==='ally'){this.hitTime=this.time;if(ship===this.leader)this.event('playerHit');}if(ship.hp===0){this.event('explosion',{pos:[...ship.pos],team});if(team==='enemy')this.kills++;}}
 spawnFor(p){if(!p.hostile||this.spawned.has(p.id))return;this.spawned.add(p.id);const rand=rng(p.seed);for(let i=0;i<3+(p.id%3);i++){const toward=norm(sub(this.leader.pos,p.pos));const pos=add(add(p.pos,mul(toward,p.radius+500)),[(rand()-.5)*260,(rand()-.5)*150,(rand()-.5)*260]);this.enemies.push({id:this.nextId++,name:'Sentinel',pos,vel:[0,0,0],dir:toward,hp:100,fire:1+rand()*2,planet:p.id});}this.event('encounter',{name:p.name});}
 step(dt,input={}){if(this.paused||this.over)return;dt=clamp(dt,0,.05);this.time+=dt;this.refresh-=dt;if(this.refresh<=0){this.refresh=.3;this.localPlanets=this.planets.filter(p=>dist(p.pos,this.leader.pos)<p.radius+9000);}
 for(const k of ['missile','rail'])this.cooldowns[k]=Math.max(0,this.cooldowns[k]-dt);
 if(input.c){if(!this.cloneLatch){this.cloneProgress+=dt;if(this.cloneProgress>=1.2){this.replicate();this.cloneLatch=true;this.cloneProgress=0;}}}else{this.cloneProgress=0;this.cloneLatch=false;}
 if(input.one)this.fire('missile');if(input.two)this.fire('rail');
 let dir=this.forward();const right=[Math.cos(this.yaw),0,Math.sin(this.yaw)];let drive=[0,0,0];const manual=input.w||input.s||input.a||input.d||input.up||input.down||Math.abs(input.throttle||0)>.04||Math.abs(input.strafe||0)>.04;if(manual)this.autopilot=false;
 if(this.autopilot){const p=this.planets[this.targetPlanet],delta=sub(p.pos,this.leader.pos),distance=length(delta);if(distance<p.radius+340){this.autopilot=false;this.warp=false;this.leader.vel=[0,0,0];this.event('arrival',{name:p.name});}else{dir=norm(delta);this.yaw=Math.atan2(dir[0],-dir[2]);this.pitch=Math.asin(dir[1]);drive=dir;}}
 else{drive=add(mul(dir,clamp((input.w?1:0)-(input.s?1:0)+(input.throttle||0),-1,1)),mul(right,clamp((input.d?1:0)-(input.a?1:0)+(input.strafe||0),-1,1)));drive[1]+=(input.up?1:0)-(input.down?1:0);if(length(drive)>1)drive=norm(drive);}
 let speed=this.warp||this.autopilot?6500:input.boost?240:88;const nearest=this.localPlanets.reduce((v,p)=>Math.min(v,dist(this.leader.pos,p.pos)-p.radius),Infinity);if(nearest<1000&&(this.warp||this.autopilot))speed=Math.max(100,Math.min(speed,(nearest-40)*3));
 const desired=mul(drive,speed),blend=1-Math.exp(-dt*(input.brake?12:this.warp||this.autopilot?7:3.4));this.leader.vel=add(this.leader.vel,mul(sub(desired,this.leader.vel),blend));if(input.brake)this.leader.vel=mul(this.leader.vel,Math.exp(-dt*10));const old=[...this.leader.pos];this.leader.pos=this.repel(add(old,mul(this.leader.vel,dt)),old);this.leader.dir=dir;
 for(const p of this.localPlanets){const d=dist(p.pos,this.leader.pos)-p.radius;if(d<1000)this.visited.add(p.id);if(d<1500)this.spawnFor(p);}
 const living=this.enemies.filter(e=>e.hp>0&&dist(e.pos,this.leader.pos)<2200);let slot=0;for(const s of this.ships){if(s===this.leader||s.hp<=0)continue;slot++;const count=this.ships.length-1,columns=Math.min(7,count),row=Math.floor((slot-1)/columns),col=(slot-1)%columns,rows=Math.ceil(count/columns),width=Math.min(columns,count-row*columns);const x=count===1?44:(col-(width-1)/2)*44,y=(row-(rows-1)/2)*28+26,up=[-Math.sin(this.yaw)*Math.sin(this.pitch),Math.cos(this.pitch),Math.cos(this.yaw)*Math.sin(this.pitch)];let formation=add(this.leader.pos,add(mul(right,x),mul(up,y)));formation=add(formation,mul(dir,90+Math.min(count,7)*14+row*32));const previous=[...s.pos];s.pos=this.repel(add(s.pos,mul(sub(formation,s.pos),1-Math.exp(-dt*2.4))),previous);s.vel=mul(sub(s.pos,previous),1/dt);s.dir=[...dir];s.fire-=dt;if(living.length&&s.fire<=0){const target=living.reduce((a,b)=>dist(a.pos,s.pos)<dist(b.pos,s.pos)?a:b);if(dist(target.pos,s.pos)<1100){this.fire(slot%4===0?'missile':'rail',s,target);s.fire=1.1+(slot%7)*.12;}}}
 for(const e of this.enemies){if(e.hp<=0)continue;const d=dist(e.pos,this.leader.pos);if(d>3800)continue;const candidates=this.ships.filter(s=>s.hp>0);if(!candidates.length)break;let victim=candidates.reduce((a,b)=>dist(a.pos,e.pos)<dist(b.pos,e.pos)?a:b);const delta=sub(victim.pos,e.pos);e.dir=norm(delta);const side=[-e.dir[2],0,e.dir[0]];const move=add(mul(e.dir,dist(victim.pos,e.pos)>250?54:-24),mul(side,25*Math.sin(this.time+e.id)));const old=[...e.pos];e.pos=this.repel(add(e.pos,mul(move,dt)),old,12);e.fire-=dt;if(dist(e.pos,victim.pos)<900&&e.fire<=0){e.fire=2.2;const end=[...victim.pos];let blocked=false;for(const p of this.localPlanets)if(segmentSphere(e.pos,end,p.pos,p.radius)!==null)blocked=true;if(!blocked){this.damage(victim,9,'ally');this.event('beam',{from:[...e.pos],to:end,team:'enemy',hit:true});}}}
 for(const m of this.missiles){m.life-=dt;const target=this.enemies.find(e=>e.id===m.target&&e.hp>0);if(target){const desired=norm(sub(target.pos,m.pos));m.dir=norm(add(m.dir,mul(sub(desired,m.dir),Math.min(1,dt*4))));}const old=[...m.pos];m.speed=Math.min(560,m.speed+dt*180);m.pos=add(m.pos,mul(m.dir,m.speed*dt));let closest=1,hit=null;for(const e of this.enemies){const t=segmentSphere(old,m.pos,e.pos,17);if(e.hp>0&&t!==null&&t<closest){closest=t;hit=e;}}for(const p of this.localPlanets){const t=segmentSphere(old,m.pos,p.pos,p.radius);if(t!==null&&t<closest){closest=t;hit=null;m.life=0;}}if(hit){this.damage(hit,65,'enemy');m.life=0;}if(m.life<=0)this.event('spark',{pos:m.pos});}
 this.missiles=this.missiles.filter(m=>m.life>0);this.enemies=this.enemies.filter(e=>e.hp>0);this.ships=this.ships.filter(s=>s.hp>0);if(!this.ships.length){this.over=true;this.event('gameover');}else if(this.leader.hp<=0){this.leader=this.ships[0];this.autopilot=false;this.warp=false;this.event('transfer');}if(this.time-this.hitTime>12){for(const s of this.ships)s.hp=Math.min(100,s.hp+dt*.6);}
 }
}
